    _init_completion -s || return

    local opts="-h --help --config -c --output -o --output-format --mode --phi --multistart --no-multistart --multistart-n --max-iterations --tolerance --initial-D0 --initial-alpha --initial-D-offset --initial-gamma-dot-t0 --initial-gamma-dot-t-offset --initial-beta --initial-v-beta --initial-v0 --initial-v-offset --initial-phi0 --initial-f0 --initial-f1 --initial-f2 --initial-f3 --verbose -v --quiet -q --threads --no-jit --plot --no-plot --save-plots --plotting-backend --parallel-plots --phi-angles --plot-experimental-data --plot-simulated-data --contrast --offset-sim --version"

    case "$prev" in
        --config|-c)
            mapfile -t COMPREPLY < <(compgen -W "$(_xpcsjax_get_config_files)" -- "${cur}")
            return
            ;;
        --output|-o)
            _filedir -d
            return
            ;;
        --output-format)
            mapfile -t COMPREPLY < <(compgen -W "json npz both" -- "${cur}")
            return
            ;;
        --mode)
            mapfile -t COMPREPLY < <(compgen -W "static_anisotropic static_isotropic laminar_flow two_component" -- "${cur}")
            return
