        --threads)
            local cpu_count
            cpu_count=$(nproc 2>/dev/null || echo 4)
            mapfile -t COMPREPLY < <(compgen -W "1 2 4 8 ${cpu_count}" -- "${cur}")
            return
            ;;
        --plotting-backend)
            mapfile -t COMPREPLY < <(compgen -W "auto matplotlib datashader" -- "${cur}")
            return
            ;;
    esac

    if [[ "$cur" == -* ]]; then
        mapfile -t COMPREPLY < <(compgen -W "${opts}" -- "${cur}")
        return
    fi
}


